function bmiCompute(weightKg, heightCm){
  weightKg=Number(weightKg); heightCm=Number(heightCm);
  if(!(weightKg>0)) return { error:'体重须为正' };
  if(!(heightCm>0)) return { error:'身高须为正' };
  var m=heightCm/100, bmi=weightKg/(m*m);
  var cat = bmi<18.5 ? '偏瘦' : (bmi<24 ? '正常' : (bmi<28 ? '超重' : '肥胖'));
  var low=18.5*m*m, high=23.9*m*m;
  return { error:null, bmi:Math.round(bmi*10)/10, category:cat,
    healthyLow:Math.round(low*10)/10, healthyHigh:Math.round(high*10)/10 };
}
function bmiBodyFat(bmi, age, sex){
  if(!(age>0)) return { error:'年龄须为正' };
  var s=(sex===1||sex==='1'||sex==='male')?1:0;
  var bf=1.20*bmi + 0.23*age - 10.8*s - 5.4;
  return { error:null, bodyFat:Math.round(bf*10)/10 };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { bmiCompute:bmiCompute, bmiBodyFat:bmiBodyFat };
}
if (typeof window !== 'undefined') {
  window.BmiForgePure = { bmiCompute:bmiCompute, bmiBodyFat:bmiBodyFat };
}
